\label{oddresult} Let $S$ be the variety  defined as in (\ref{defofSr}) or (\ref{defofS}). If $d\geq 3$ is odd, then we have
\begin{equation}\label{general1}R^*\left(2\to \frac{2d+2}{d-1}\right)\lesssim 1,\end{equation}
 and if $d\geq 4$ is even, then 
\begin{equation} \label{sharp22} R^*\left(2\to \frac{2d}{d-2}\right)\lesssim 1.\end{equation}
In addition, there exist specific varieties $S$ for which each result of (\ref{general1}) and (\ref{sharp22}) gives  a sharp $L^2-L^r$ extension estimate.

\label{mainpaper} Let $S$ be the algebraic variety in $({\mathbb F_{q}^d},dx)$ defined as in (\ref{defofSr}) or (\ref{defofS}). If $d\geq 3$ is odd, then we have
\begin{equation}\label{sharpodda} A(p\to r)\lesssim 1 ~~\iff ~~ \left(\frac{1}{p}, \frac{1}{r}\right) \in {\mathbb T},\end{equation}
where ${\mathbb T}$ denotes the convex hull of points $(0,0), (0,1),(1,1)$ and $(d/(d+1), 1/(d+1)).$
On the other hand, if $d\geq 4$ is even, then
\begin{equation}\label{sharpupto}A(p\to r)\lesssim  1 \quad \mbox{for}~~ \left(\frac{1}{p}, \frac{1}{r}\right) \in \Omega\setminus\{P_1,P_2\} \end{equation}
where $\Omega$ denotes  the convex hull of points $(0,0), (0,1), (1,1),$
$$P_1= \left(\frac{d^2-2d+2}{d(d-1)}, \frac{1}{(d-1)}  \right)~~\mbox{and}~~ P_2=\left(\frac{d-2}{d-1}, \frac{d-2}{d(d-1)}  \right).$$
In addition, if $d\geq 4$ is even and $P_1=(1/p, 1/r)$ then the restricted strong-type estimate 
\begin{equation}\label{sharpupto1} \|f\ast d\sigma\|_{L^r(\mathbb F_q^d, dx)}\lesssim \|f\|_{L^{p,1}(\mathbb F_q^d, dx)}\end{equation}
holds, and if $d\geq 4$ is even and $P_2=(1/r^\prime, 1/p^\prime)$ then the weak-type estimate 
\begin{equation}\label{sharpupto2} \|f\ast d\sigma\|_{L^{p^\prime, \infty}(\mathbb F_q^d, dx)} \lesssim \|f\|_{L^{r^\prime}(\mathbb F_q^d, dx)}\end{equation}
holds.
Finally,  the averaging results in even dimensions  are sharp in the sense that  if $(1/p, 1/r) \notin \Omega$ and $S$ contains a $d/2$-dimensional subspace, then  $L^p-L^r$ averaging estimate is impossible.

\label{neave}
 For  $a_j\neq 0, j=1,\dots,d,$ let $S=\{x\in {\mathbb F_{q}^d}: a_1x_1^2+ \cdots+a_dx_d^2=0\}.$
Then $A(p\to r)\lesssim 1$ only if $(1/p, 1/r)$ lies in the convex hull of the points 
\begin{equation}\label{N4}(0,0),(0,1),(1,1), ~\mbox{and}~ \left(\frac{d}{d+1}, \frac{1}{d+1}\right).\end{equation}
Moreover, if $d\geq 4$ is even and $S$ contains a $d/2-$dimensional affine subspace $H$, then $A(p\to r)\lesssim 1$ only if $(1/p, 1/r)$ lies in the convex hull of the points $(0,0),(0,1),(1,1),$ 
\begin{equation}\label{N5} \left( \frac{d^2-2d+2}{d(d-1)}, \frac{1}{d-1}\right), ~\mbox{and}~\left(\frac{d-2}{d-1},\frac{d-2}{d(d-1)} \right).\end{equation}

\label{decay} If $d\geq 3$ is odd, then it follows that
\begin{equation}\label{odddecay}\begin{array}{ll}(d\sigma)^\vee(0,\dots,0)= 1, \quad & \\
|(d\sigma)^\vee(m)|\lesssim q^{-\frac{(d-1)}{2}}\quad &\mbox{if}~~ m\neq (0,\dots,0), \end{array}\end{equation}

and if $d\geq 4$ is even, then we have
\begin{equation}\label{evendecay}\begin{array}{ll} (d\sigma)^\vee(0,\dots,0)= 1, \quad &\\
|(d\sigma)^\vee(m)|\lesssim q^{-\frac{(d-2)}{2}} \quad &\mbox{if}~~m\neq (0,\dots,0). \end{array}\end{equation}

Consider a function $K$ on $({\mathbb F_q^d}, dm)$ defined as $K=(d\sigma)^\vee -\delta_0.$
We want to prove that for every function $f$ on $({\mathbb F_q^d},dx)$, 
$$\|f\ast d\sigma\|_{L^{\alpha+2}({\mathbb F_q^d},dx)}\lesssim \|f\|_{L^{\frac{\alpha+2}{\alpha+1}}({\mathbb F_q^d},dx)}.$$
Since $d\sigma= \widehat{K}+\widehat{\delta_0}= \widehat{K}+1$ and $\|f\ast 1\|_{L^{\alpha+2}({\mathbb F_q^d},dx)}\lesssim \|f\|_{L^{\frac{\alpha+2}{\alpha+1}}({\mathbb F_q^d},dx)}$, it suffices to show that for every $f$ on $({\mathbb F_q^d},dx),$
\begin{equation}
\|f\ast \widehat{K}\|_{L^{\alpha+2}({\mathbb F_q^d},dx)}\lesssim \|f\|_{L^{\frac{\alpha+2}{\alpha+1}}({\mathbb F_q^d},dx)}.
\end{equation}
Notice that this  can be done by interpolating the following two estimates:
\begin{equation}\label{first1}
\|f\ast \widehat{K}\|_{L^2({\mathbb F_q^d},dx)}\lesssim  q^{-\frac{\alpha}{2}}\|f\|_{L^2({\mathbb F_q^d},dx)}
\end{equation}
and 
\begin{equation}\label{second2}
\|f\ast \widehat{K}\|_{L^{\infty}({\mathbb F_q^d},dx)}\lesssim  q \|f\|_{L^1({\mathbb F_q^d},dx)}.
\end{equation}
The inequality (\ref{first1}) follows from  the Plancherel theorem, the size assumption of $|(d\sigma)^\vee|$, and the definition of $K.$
On the other hand, the inequality (\ref{second2}) follows from Young's inequality and the observation that $\|\widehat{K}\|_{L^\infty({\mathbb F_q^d},dx)}\lesssim q.$ Thus, the proof of Lemma \ref{Carbery} is complete.
